import { after } from 'next/server';
import { logPageView } from '@/lib/analytics';

export default function Home() {
  // Schedule analytics logging to run after the response is sent
  // This uses Next.js's after() function which ensures the work doesn't block the response
  after(async () => {
    await logPageView('/home', new Date().toISOString());
  });

  return (
    <main>
      <h1>Welcome to Our Site!</h1>
      <p>This page logs analytics without blocking the response.</p>
      <p>The page view has been recorded in the background.</p>
    </main>
  );
}

